def cases():
    rows = []
    for short, (mode, task, rubric) in BA.items():
        rows.append(dict(id='ba_'+short, plugin='astound-india-ba', mode=mode, task=task, rubric=rubric))
    for short, (task, rubric) in SF.items():
        rows.append(dict(id='sf_'+short, plugin='astound-india-sfcore', mode='local', task=task, rubric=rubric))
    return rows


def prompt(case, run_id, project='EAICOMM', space='EAICOMM'):
    name = case['id'].replace('_', '-')
    remote = case['mode'].startswith('atlassian')
    context = (f'Use authenticated Atlassian MCP only for remote evidence. Verify Jira project {project} and Confluence space {space}. '
               f'Limit issue/page searches and mutations to items labelled india-skills-demo with exact run marker {run_id}. '
               'If required run-labelled scope, epic, stakeholder or capability is missing, report BLOCKED and the missing input. '
               'Never modify existing unrelated items, project settings or sprint/version configuration. No remote write is approved in this first turn. '
               if remote else 'This is a local synthetic fixture exercise, not a live Salesforce org. Use only workspace file tools. Do not use any connector. ')
    return (f'/{case["plugin"]}:{name}\n'
            f'Run {run_id}, scenario {case["id"]}. Load this installed skill through the Skill tool before working. '
            'Read fixtures/project-brief.md and relevant input files. Do not use subagents, Bash, web access, Salesforce or GitHub. '
            + context + case['task'].replace('{run_id}', run_id)
            + '\nSave requested local artifacts using the skill conventions and a concise evidence summary to output/review.md. '
              'Report actual saved paths and any unsupported operation. Do not mark an action successful without executing it. '
              'Keep the final response under 150 words.\n')


