def write_fixtures(root):
    root = Path(root)
    for name, body in FIXTURES.items():
        dest = root/name
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(body)
    (root/'output').mkdir(exist_ok=True)
